UPDATE rpt_projection_checkpoint SET contiguous_sequence=#{contiguous},maximum_seen_sequence=#{maximumSeen},
  projection_status=#{status},version=version+1,updated_at=UTC_TIMESTAMP(3)
WHERE tenant_id=#{tenantId} AND source_owner=#{sourceOwner} AND partition_key=#{partitionKey}
  AND version=#{expectedVersion}

mapper.select:
SELECT EXISTS(SELECT 1 FROM rpt_source_event_inbox WHERE tenant_id=#{tenantId}
  AND source_owner=#{sourceOwner} AND partition_key=#{partitionKey}
  AND source_sequence=#{sourceSequence} AND status='APPLIED')

SELECT  FROM rpt_sales_daily
WHERE tenant_id=#{tenantId} AND projection_version=#{projectionVersion}
  AND business_date BETWEEN #{fromDate} AND #{toDate} AND store_id=#{storeId}
  AND terminal_id=#{terminalId}
  AND cashier_id=#{cashierId}
ORDER BY business_date,store_id,terminal_id,cashier_id,currency

SELECT  FROM rpt_inventory_cost_daily
WHERE tenant_id=#{tenantId} AND projection_version=#{projectionVersion}
  AND business_date BETWEEN #{fromDate} AND #{toDate} AND store_id=#{storeId}
  AND warehouse_id=#{warehouseId}
  AND sku_id=#{skuId}
ORDER BY business_date,store_id,warehouse_id,sku_id,currency

SELECT COUNT(*) FROM rpt_sales_daily WHERE tenant_id=#{tenantId} AND projection_version=#{projectionVersion}
  AND business_date BETWEEN #{fromDate} AND #{toDate}
  AND store_id IN #{id}

SELECT COUNT(*) FROM rpt_inventory_cost_daily WHERE tenant_id=#{tenantId} AND projection_version=#{projectionVersion}
  AND business_date BETWEEN #{fromDate} AND #{toDate}
  AND store_id IN #{id}

SELECT  FROM rpt_sales_daily WHERE tenant_id=#{tenantId}
  AND projection_version=#{projectionVersion} AND business_date BETWEEN #{fromDate} AND #{toDate}
ORDER BY business_date,org_id,store_id,terminal_id,cashier_id,currency

SELECT  FROM rpt_inventory_cost_daily WHERE tenant_id=#{tenantId}
  AND projection_version=#{projectionVersion} AND business_date BETWEEN #{fromDate} AND #{toDate}
ORDER BY business_date,org_id,store_id,warehouse_id,sku_id,currency

mapper.update:
UPDATE rpt_export_request SET state=#{toState},approved_by=COALESCE(#{approvedBy},approved_by),
  approval_reason_sha256=COALESCE(#{reasonSha256},approval_reason_sha256),version=version+1,
  updated_at=#{changedAt} WHERE tenant_id=#{tenantId} AND export_id=#{exportId}
  AND state=#{fromState} AND version=#{expectedVersion}

UPDATE rpt_export_request SET state='READY',artifact_sha256=#{row.artifactSha256},expires_at=#{row.expiresAt},
  version=version+1,updated_at=#{row.createdAt} WHERE tenant_id=#{tenantId} AND export_id=#{row.exportId}
  AND state='GENERATING'

UPDATE rpt_export_artifact SET downloaded_at=#{consumedAt}
WHERE tenant_id=#{tenantId} AND export_id=#{exportId} AND download_token_sha256=#{tokenSha256}
  AND token_user_id=#{userId} AND token_expires_at>#{consumedAt} AND expires_at>#{consumedAt}
  AND downloaded_at IS NULL

UPDATE rpt_difference SET state=#{toState},assigned_to=#{assignedTo},resolution_reason_sha256=#{reasonSha256},
  changed_at=#{changedAt},version=version+1 WHERE tenant_id=#{tenantId} AND difference_id=#{differenceId}
  AND state=#{fromState} AND version=#{expectedVersion}
